import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class NthElementCullerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<String> listOf(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    public static void main(String[] args) {
        try {
            List<String> letters = listOf("a", "b", "c", "d", "e");
            check("removeEveryNth(5 items, 2) returns", 2, NthElementCuller.removeEveryNth(letters, 2));
            check("removeEveryNth(5 items, 2) list", "[a, c, e]", letters.toString());

            List<String> everyOne = listOf("a", "b", "c");
            NthElementCuller.removeEveryNth(everyOne, 1);
            check("n of 1 leaves an empty list", "[]", everyOne.toString());

            List<String> untouched = listOf("a", "b", "c");
            check("n of 0 removes nothing", 0, NthElementCuller.removeEveryNth(untouched, 0));
            check("n of -3 removes nothing", 0, NthElementCuller.removeEveryNth(untouched, -3));
            check("refused n values leave the list alone", "[a, b, c]", untouched.toString());

            List<String> seven = listOf("1", "2", "3", "4", "5", "6", "7");
            check("n of 3 on 7 items", 2, NthElementCuller.removeEveryNth(seven, 3));
            check("n of 3 on 7 items list", "[1, 2, 4, 5, 7]", seven.toString());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

