import java.util.List;

public class NthElementCuller {

    public static int removeEveryNth(List<String> items, int n) {
        if (n < 1) {
            return 0;
        }
        int removed = 0;
        for (int i = items.size() - 1; i >= 0; i--) {
            if ((i + 1) % n == 0) {
                items.remove(i);
                removed++;
            }
        }
        return removed;
    }
}
